Tôi đã thêm CSS để tạo giao diện chuyên nghiệp, bổ sung tiêu đề hướng dẫn, căn giữa nội dung và sử dụng `mouseout` làm delay ẩn để tránh lỗi tải trang trên điện thoại.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Debounce Search Example</title>
    <style>
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: #f4f7f6;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            margin: 0;
        }
        .search-card {
            background: white;
            padding: 2rem;
            border-radius: 12px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.1);
            width: 350px;
            max-width: 600px;
        }
        h1 { color: #333; font-size: 1.5rem; text-align: center; }

        /* thẻ ul chứa kết quả tìm kiếm */
        .results {
            list-style: none;
            padding: 0;
            margin: 0;
            background: #eee;
            font-size: 0.9rem;
        }
        .result-item {
            margin-bottom: 1.5rem;
            padding: 1rem 2rem;
            border: 1px solid #ddd;
            border-radius: 6px;
            background: white;
            font-weight: bold;
            cursor: pointer;
            transition: background 0.3s;
        }
        .result-item:hover { background-color: #eef; }

        /* Các nút bấm điều hướng */
        .btn-search {
            background: #282c34;
            color: white;
            border: none;
            padding: 12px 20px;
            font-size: 1rem;
            border-radius: 6px;
            cursor: pointer;
            width: 40%;
            transition: background 0.3s;
        }
        .btn-search:hover { background-color: #2980b9; }

        /* Tiêu đề hướng dẫn */
        .guide-title { color: #666; font-size: 0.85rem; margin-bottom: 1.5rem; text-align: center; }

        /* Nút submit */
        .submit-btn {
            background: #282c34;
            color: white;
            border: none;
            padding: 12px 20px;
            font-size: 1rem;
            border-radius: 6px;
            cursor: pointer;
            width: 40%;
            transition: background 0.3s;
        }
        .submit-btn:hover { background-color: #2980b9; }

        /* Thẻ ul với kết quả tìm kiếm */
        .result-list { list-style: none; padding: 0; margin: 0; }
        .result-list li { padding: 1rem 1.25rem; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; }
        .result-item { background: white; padding: 1rem; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1); max-width: 400px; margin-bottom: 1.5rem; }
        .result-item:hover { background-color: #eef; }

        /* Tiêu đề thẻ header */
        header { background: #282c34; color: white; padding: 1rem; text-align: center; font-weight: bold; }
        header h2 { font-size: 1.2rem; margin-bottom: 0.5rem; }

        pre { background: #282c34; color: white; padding: 1rem; border-radius: 8px; overflow-x: auto; font-size: 1rem; }
    </style>
</head>
<body>

<div class="search-card">
    <h1>Search Results</h1>
    <div class="results">
        <li class="result-item"><span>Laptop</span></li>
        <li class="result-item"><span>Smartphone</span></li>
    </div>
</div>

<script>
  document.getElementById('search-btn').addEventListener('click', function() {
        const btn = document.getElementById('search-btn');
        let resultsLink = this.href;

        btn.disabled = false;
        btn.innerText = 'Get Results';
        btn.onclick = () => {
            resultsLink = this.href === '#' ? '' : '&gt;';

            fetch('/api/search?q=' + encodeURIComponent(this.innerText) + resultsLink)
                .then(response => response.json())
                .then(data => {
                    resultsLink = this.href === '#' ? '' : '&gt;';
                    console.log('Response: ', data);
                })
                .catch(error => console.error('Error fetching data:', error));
        };
    });

  document.getElementById('submit-btn').addEventListener('click', function() {
        const btn = document.getElementById('submit-btn');
        let resultsLink = this.href;

        btn.disabled = false;
        btn.innerText = 'Search';
        btn.onclick = () => {
            resultsLink = this.href === '#' ? '' : '&gt;';

            fetch('/api/search?q=' + encodeURIComponent(this.innerText) + resultsLink)
                .then(response => response.json())
                .then(data => {
                    resultsLink = this.href === '#' ? '' : '&gt;';
                    console.log('Response: ', data);
                })
                .catch(error => console.error('Error fetching data:', error));
        };
    })
